var t=`1316-chaja-cake`;var a=`world-1316`;var r=`UY`;var s=`south-america`;var n=8;var o=220;var g={en:`Chajá Cake`,ua:`Торт чаха`};var h={en:`Chajá Cake is a dish from Uruguay featuring all-purpose flour, chicken egg, baking powder, pasteurized egg whites. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Торт чаха, страва кухні країни Уругвай з такими основними складниками: пшеничне борошно універсальне, куряче яйце, розпушувач тіста, пастеризовані яєчні білки. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:12,i:[[`all-purpose-flour`,240,`g`],[`chicken-egg`,4,`pcs`],[`white-granulated-sugar`,190,`g`],[`baking-powder`,12,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 28 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 28 хвилин до готовності.`,t:[`baking`],m:28,i:[]},{en:`Whip pasteurized egg whites with sugar into firm peaks; pipe small meringues onto parchment.`,ua:`Збийте пастеризовані білки з цукром до стійких піків та відсадіть маленькі меренги на пергамент.`,t:[`whipping`],m:12,i:[[`pasteurized-egg-whites`,110,`ml`],[`white-granulated-sugar`,90,`g`]]},{en:`Dry the small meringues slowly at about 110°C until crisp and light; cool before layering.`,ua:`Повільно підсушуйте маленькі меренги приблизно при 110°C до сухої хрусткості; остудіть перед складанням.`,t:[`baking`],m:55,i:[]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:9,i:[[`whipping-cream`,450,`ml`],[`powdered-sugar`,75,`g`]]},{en:`Layer completely cooled sponge, cream, sliced peaches and dry meringue; refrigerate until slices hold their shape.`,ua:`Викладайте шарами охолоджений бісквіт, крем, персики та суху меренгу; охолоджуйте до стабілізації торта.`,t:[`layered-assembly`],m:14,i:[[`peach`,350,`g`]]},{en:`Refrigerate the prepared mixture for about 90 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 90 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:90,i:[]}];var l={slug:t,id:a,country:`UY`,region:s,servings:8,minutes:220,title:g,text:h,steps:u};export{r as country,l as default,a as id,o as minutes,s as region,n as servings,t as slug,u as steps,h as text,g as title};